ValidationRule.errorConditionFormula:
AND(
    RecordType.DeveloperName = "Partner_Community_Supplier",
    OR(
        AND(
            NOT(Agreement_Signed__c),
            OR(
                NOT(ISBLANK(Agreement_Start_Date__c)),
                NOT(ISBLANK(Agreement_End_Date__c))
            )
        ),
        AND(
            Agreement_Signed__c,
            OR(
                ISBLANK(Agreement_Start_Date__c),
                ISBLANK(Agreement_End_Date__c)
            )
        )
    )
)
